]$wording$::jsonb;
 corrected integer;
begin
 -- Every source must identify exactly one row, including archived rows. A missing
 -- source and a duplicate source must not cancel out in a total row-count check.
 if exists(select 1 from jsonb_array_elements(edits) entry
  where (select count(*) from ojjuda_arcade_internal.drinking_truth_cards c where c.flavor=(entry->'from')->>'flavor' and c.body=(entry->'from')->>'body')<>1) then
  raise exception 'truth_wording_source_changed';
 end if;
 -- A prior spelling may already belong to this card, never to a different one.
 if exists(select 1 from jsonb_array_elements(edits) entry
  join ojjuda_arcade_internal.drinking_truth_cards c on c.flavor=(entry->'from')->>'flavor' and c.body=(entry->'from')->>'body'
  join ojjuda_arcade_internal.drinking_truth_history h
   on h.fingerprint=ojjuda_arcade_internal.drinking_prompt_fingerprint('truth',c.flavor,(entry->'to')->>'body')
  where h.card_id is distinct from c.id) then raise exception 'truth_wording_history_conflict'; end if;
 with changed as (
  update ojjuda_arcade_internal.drinking_truth_cards c set body=(entry->'to')->>'body',revision=c.revision+1
  from jsonb_array_elements(edits) entry where c.flavor=(entry->'from')->>'flavor' and c.body=(entry->'from')->>'body'
  returning c.id,c.flavor,c.body
 ), remembered as (
  insert into ojjuda_arcade_internal.drinking_truth_history(fingerprint,card_id)
  select ojjuda_arcade_internal.drinking_prompt_fingerprint('truth',flavor,body),id from changed
  on conflict(fingerprint) do nothing returning card_id
 )
 select count(*) into corrected from changed;
 if corrected<>188 then raise exception 'truth_wording_row_count_changed'; end if;
end;
