]$wording$::jsonb;
 corrected integer;
begin
 -- Every source must identify exactly one row, including archived rows. A missing
 -- source and a duplicate source must not cancel out in a total row-count check.
 if exists(select 1 from jsonb_array_elements(edits) entry
  where (select count(*) from ojjuda_arcade_internal.drinking_content_items c where c.kind='minority' and c.body=(entry->'from')->>0 and c.second is not distinct from (entry->'from')->>1 and c.prompt_flavor=entry->>'flavor')<>1) then
  raise exception 'minority_wording_source_changed';
 end if;
 -- The existing remember trigger adds new king/fingers/imagevote fingerprints;
 -- older fingerprints and moderation records remain intact.
 update ojjuda_arcade_internal.drinking_content_items c set body=(entry->'to')->>0,second=(entry->'to')->>1,revision=c.revision+1
 from jsonb_array_elements(edits) entry where c.kind='minority' and c.body=(entry->'from')->>0 and c.second is not distinct from (entry->'from')->>1 and c.prompt_flavor=entry->>'flavor';
 get diagnostics corrected=row_count;
 if corrected<>229 then raise exception 'minority_wording_row_count_changed'; end if;
end;
