    "to": "‘다음 여름에도 같이 갈 거지?’라는 말에 내년에도 함께인 모습을 떠올린 사람 접어"
  },
  {
    "flavor": "spicy",
    "from": "친구에게 이미 실컷 흉을 본 연인과 화해해서 다음 만남이 민망했던 사람 접어",
    "to": "친구에게 실컷 흉본 연인과 금세 화해해서 그 친구를 다시 보기 민망했던 사람 접어"
  }
]$wording$::jsonb;
 corrected integer;
begin
 -- Every source must identify exactly one row, including archived rows. A missing
 -- source and a duplicate source must not cancel out in a total row-count check.
 if exists(select 1 from jsonb_array_elements(edits) entry
  where (select count(*) from ojjuda_arcade_internal.drinking_content_items c where c.kind='fingers' and c.body=(entry->'from')#>>'{}' and c.second is not distinct from null::text and c.prompt_flavor=entry->>'flavor')<>1) then
  raise exception 'fingers_wording_source_changed';
 end if;
 -- The existing remember trigger adds new king/fingers/imagevote fingerprints;
 -- older fingerprints and moderation records remain intact.
 update ojjuda_arcade_internal.drinking_content_items c set body=(entry->'to')#>>'{}',revision=c.revision+1
 from jsonb_array_elements(edits) entry where c.kind='fingers' and c.body=(entry->'from')#>>'{}' and c.second is not distinct from null::text and c.prompt_flavor=entry->>'flavor';
 get diagnostics corrected=row_count;
 if corrected<>149 then raise exception 'fingers_wording_row_count_changed'; end if;
end;
$polish$;
commit;
